const slides = Array.from(document.querySelectorAll('.slide'));
const dots = document.querySelector('.nav-dots');
slides.forEach((_, index) => {{
  const dot = document.createElement('button');
  dot.className = 'nav-dot';
  dot.setAttribute('aria-label', `Go to slide ${{index + 1}}`);
  dot.addEventListener('click', () => goTo(index));
  dots.appendChild(dot);
}});
function currentIndex() {{
  const y = window.scrollY;
  const h = window.innerHeight;
  return Math.max(0, Math.min(slides.length - 1, Math.round(y / h)));
}}
function goTo(index) {{
  slides[index].scrollIntoView({{ behavior: 'smooth', block: 'start' }});
}}
function updateState() {{
  const index = currentIndex();
  slides.forEach((slide, i) => slide.classList.toggle('visible', i === index));
  Array.from(dots.children).forEach((dot, i) => dot.classList.toggle('active', i === index));
}}
document.addEventListener('keydown', (event) => {{
  if (['ArrowRight', 'PageDown', ' '].includes(event.key)) {{ event.preventDefault(); goTo(Math.min(slides.length - 1, currentIndex() + 1)); }}
  if (['ArrowLeft', 'PageUp'].includes(event.key)) {{ event.preventDefault(); goTo(Math.max(0, currentIndex() - 1)); }}
}});
window.addEventListener('scroll', updateState, {{ passive: true }});
window.addEventListener('resize', updateState);
updateState();
  </script>
